const Get = key => Object.freeze({ type: 'Get', key });
const Put = (key, value) => Object.freeze({ type: 'Put', key, value });

async function run(op, store) {
  switch (op.type) {
    case 'Get': return store.get(op.key);
    case 'Put': return store.put(op.key, op.value);
    default: throw new Error(`unknown op: ${op.type}`);
  }
}

